import json


def read_json(path, default=None):
    try:
        raw = api.files.read(file=path)
    except Exception:
        return default
    try:
        return json.loads(raw)
    except Exception:
        return default


responses = params.get("responses") or {}
todo_id = params.get("todo_id") or ""
outcome = "ignored"

if responses and todo_id:
    draft = read_json("PracticeManager/NoShowDrafts/" + todo_id + ".json", None)
    if not draft:
        api.workq.comment(todo_id=todo_id, body="Couldn't find the drafted follow-up for this item — nothing was sent.")
        outcome = "draft_missing"
    else:
        decision = str(responses.get("q_decision") or "")
        edited = str(responses.get("q_edited_message") or "").strip()
        patient_name = draft.get("patient_name") or "the patient"

        if decision == "Don't send":
            api.workq.comment(todo_id=todo_id, body="Marked as don't send. No message was sent to " + patient_name + ".")
            api.workq.complete(todo_id=todo_id)
            outcome = "not_sent"
        else:
            body = edited if (decision == "Edit and send" and edited) else (draft.get("body") or "")
            subject = draft.get("subject") or "We missed you"
            email = draft.get("email") or ""
            slug = draft.get("slug") or ""
            practice = read_json("PracticeManager/Practices/" + slug + ".json", {}) or {}
            provider = str(practice.get("email_provider") or "outlook")

            if not email:
                api.workq.comment(todo_id=todo_id, body="No email on file for " + patient_name + " — nothing was sent. Send it another way if needed.")
                outcome = "no_email"
            elif provider == "outlook":
                api.connectors.invoke(
                    server="m365-mail-send",
                    tool="send_email",
                    args={"to": [email], "subject": subject, "body": body, "contentType": "Text"},
                )
                api.workq.comment(todo_id=todo_id, body="Sent to " + email + ".")
                api.workq.complete(todo_id=todo_id)
                outcome = "sent"
            else:
                # Gmail has no send tool in this workspace today — never claim it was sent.
                api.workq.comment(
                    todo_id=todo_id,
                    body=(
                        "This practice's email provider is Gmail, which isn't wired up for sending yet. "
                        "Please send this yourself:\n\n**To:** " + email + "\n**Subject:** " + subject + "\n\n" + body
                    ),
                )
                outcome = "needs_manual_send"

            if outcome == "sent" and draft.get("patient_id"):
                try:
                    hist = api.connectors.invoke(
                        server="cliniko-scheduling",
                        tool="list_individual_appointments",
                        args={
                            "q": ["did_not_arrive:=true", "patient_id:=" + str(draft["patient_id"])],
                            "per_page": 100,
                        },
                    )
                    count = len((hist or {}).get("individual_appointments") or [])
                except Exception:
                    count = 0
                if count >= 2:
                    reviewer = practice.get("reviewer_id") or ""
                    api.workq.create(
                        title="Repeat no-show: " + patient_name,
                        scope="org",
                        description=(
                            patient_name + " has " + str(count) + " recorded no-shows in Cliniko. "
                            "Worth a conversation before their next booking."
                        ),
                        priority="normal",
                        assignee_ids=[reviewer] if reviewer else None,
                        labels=["healthcare-practice-management", "no-show-recovery", "repeat-no-show"],
                    )
